  "day10_wood_fence_materials.jpg": "",
  "day11_vinyl_plank_lvp.jpg": "",
  "day12_brick_mortar_wall.jpg": "",
  "day13_sod_turf_lawn.jpg": "",
  "day14_wallpaper_repeat_rolls.jpg": "",
  "day15_drywall_wall_area.jpg": "",
  "day16_cinder_block_cmu.jpg": "",
  "day17_carpet_square_yards.jpg": "",
  "day18_skirting_baseboard_trim.jpg": "",
  "day19_ceiling_paint_sloped.jpg": "",
  "day20_flooring_waste_guide.jpg": "",
  "day21_tile_trowel_thinset.jpg": "",
  "day22_sqft_to_m2_converter.jpg": "",
  "day23_topsoil_raised_bed.jpg": "",
